def join_path(self, *args):
    parts = []
    for arg in args:
        arg = arg.replace('/', '\\')
        parts.extend([a for a in arg.split('\\') if a])
    path = '\\'.join(parts)
    if path.startswith('~~'):
        return path
    if path.startswith('~'):
        return '\\' + path
    return path
